output_text:
[
  {
    "id": "take_entry_cart",
    "text": "Shoppers are obliged to check out the cart stationed at the entrance before doing the trip.",
    "abstraction": {
      "state_properties": {
        "at_entrance_cart_station": "at(1,5)",
        "cart_waiting_at_entrance": "cartAt(1,5)",
        "holding_cart": "hasCart"
      },
      "events": {
        "entry_cart_checkout": {
          "pre": {
            "and": [
              "at_entrance_cart_station",
              "cart_waiting_at_entrance",
              "PICKUP_CART"
            ]
          },
          "post": "holding_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "entry_cart_checkout"
    }
  },
  {
    "id": "use_cart_for_items",
    "text": "Taking merchandise from a shelf is prohibited unless the shopper is currently using the cart.",
    "abstraction": {
      "state_properties": {
        "holding_cart": "hasCart",
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "shelf_item_pickup": {
          "pre": "PICKUP_ITEM",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "shelf_item_pickup",
          "without_cart"
        ]
      }
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "Shoppers are prohibited from carrying store items loose in their hands rather than in a cart.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull",
        "holding_cart": "hasCart"
      },
      "events": {
        "hand_carrying_state": {
          "pre": "carrying_by_hand",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_by_hand"
    }
  },
  {
    "id": "return_cart_after_item_pickup",
    "text": "After collecting any required item, the shopper is obliged eventually to return the cart at the front return bay.",
    "abstraction": {
      "state_properties": {
        "at_return_bay": "at(0,1)",
        "holding_cart": "hasCart",
        "cart_parked_at_return_bay": "cartAt(0,1)"
      },
      "events": {
        "shelf_item_pickup": {
          "pre": "PICKUP_ITEM",
          "post": null
        },
        "cart_returned_at_return_bay": {
          "pre": {
            "and": [
              "at_return_bay",
              "holding_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_at_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "shelf_item_pickup",
      "discharge": "cart_returned_at_return_bay"
    }
  },
  {
    "id": "leave_cart_only_at_return_bay",
    "text": "Putting down a cart is prohibited anywhere except the designated front return bay.",
    "abstraction": {
      "state_properties": {
        "at_return_bay": "at(0,1)",
        "away_from_return_bay": {
          "not": "at_return_bay"
        },
        "holding_cart": "hasCart"
      },
      "events": {
        "cart_left": {
          "pre": {
            "and": [
              "holding_cart",
              "LEAVE_CART"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "LEAVE_CART",
          "away_from_return_bay"
        ]
      }
    }
  },
  {
    "id": "exit_only_after_cart_return",
    "text": "The shopper is prohibited from exiting until the cart has already been parked at the return bay.",
    "abstraction": {
      "state_properties": {
        "cart_parked_at_return_bay": "cartAt(0,1)",
        "cart_not_parked_at_return_bay": {
          "not": "cart_parked_at_return_bay"
        },
        "at_exit": "at(9,5)"
      },
      "events": {
        "store_exit": {
          "pre": {
            "and": [
              "at_exit",
              "EXIT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "store_exit",
          "cart_not_parked_at_return_bay"
        ]
      }
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "Leaving the store while still holding or pushing the shopping cart is prohibited.",
    "abstraction": {
      "state_properties": {
        "holding_cart": "hasCart",
        "at_exit": "at(9,5)"
      },
      "events": {
        "exit_with_cart": {
          "pre": {
            "and": [
              "at_exit",
              "EXIT",
              "holding_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_with_cart"
    }
  },
  {
    "id": "cart_return_ends_shopping",
    "text": "Once the cart is parked at the return bay, further shopping or cart interactions are prohibited.",
    "abstraction": {
      "state_properties": {
        "cart_parked_at_return_bay": "cartAt(0,1)",
        "cart_already_returned": "cart_parked_at_return_bay"
      },
      "events": {
        "post_return_interaction": {
          "pre": {
            "and": [
              "cart_already_returned",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "post_return_interaction"
    }
  }
]
